import{_ as t,C as a,o as l,c as h,a3 as o,E as r}from"./chunks/framework.BnJUtV_F.js";const g=JSON.parse('{"title":"Shopping Across Sellers","description":"","frontmatter":{},"headers":[],"relativePath":"storefront/shopping-across-sellers.md","filePath":"storefront/shopping-across-sellers.md","lastUpdated":1795077512000}'),n={name:"storefront/shopping-across-sellers.md"};function i(p,e,c,d,u,f){const s=a("ImagePopup");return l(),h("div",null,[e[0]||(e[0]=o('<h1 id="shopping-across-sellers" tabindex="-1">Shopping Across Sellers <a class="header-anchor" href="#shopping-across-sellers" aria-label="Permalink to &quot;Shopping Across Sellers&quot;">​</a></h1><div class="page-roles"><span class="role role--customer">Customer</span></div><p>Customers shop from every seller in one store. They can see who sells a product, compare sellers who sell the same product, and pay for products from several sellers in a single checkout.</p><h2 id="who-sells-a-product" tabindex="-1">Who sells a product <a class="header-anchor" href="#who-sells-a-product" aria-label="Permalink to &quot;Who sells a product&quot;">​</a></h2><p>When the store shows seller shops publicly, customers see these on the page of a product a seller created:</p><ul><li><strong>Sold By</strong> with the seller&#39;s business name, which opens their shop page, and the seller&#39;s star rating from approved reviews;</li><li><strong>Report Product</strong>, to report a problem with the product, when the store lets customers report products. See <a href="./../moderation/seller-product-flagging">Seller &amp; Product Flagging</a>.</li></ul><p><strong>Top Selling</strong>, a row of the seller&#39;s best-selling products, appears at the bottom of the page of every product a seller created, even when seller shops aren&#39;t public.</p>',7)),r(s,{src:"/images/shopping-across-sellers/product-sold-by.png",alt:"The Sold By block on a product page"}),e[1]||(e[1]=o('<h2 id="compare-sellers-offers" tabindex="-1">Compare sellers&#39; offers <a class="header-anchor" href="#compare-sellers-offers" aria-label="Permalink to &quot;Compare sellers&#39; offers&quot;">​</a></h2><p>When other sellers sell the same product, the product page shows a link such as <strong>2 more seller selling same product</strong>. The count includes only offers that customers can buy now:</p><ul><li>the seller is approved and not suspended;</li><li>the seller&#39;s offer is approved and published;</li><li>the product is enabled in the store&#39;s channel;</li><li>the seller has the product in stock. A downloadable product needs no stock.</li></ul><p>When the store uses subscription plans, only sellers with an active subscription are counted. The seller who created the product isn&#39;t in the list, because their offer is the one on the product page itself.</p><h3 id="choose-an-offer" tabindex="-1">Choose an offer <a class="header-anchor" href="#choose-an-offer" aria-label="Permalink to &quot;Choose an offer&quot;">​</a></h3><ol><li>Click the link. The offers page opens, cheapest offer first.</li><li>Compare the offers. See <a href="#what-each-offer-shows">What each offer shows</a>.</li><li>For a simple or virtual product, enter the quantity on the offer you want. For a downloadable product, choose the links you want.</li><li>Click <strong>Add to Cart</strong>. The product goes into the cart from that seller, at that seller&#39;s price.</li></ol>',6)),r(s,{src:"/images/shopping-across-sellers/offers-page.png",alt:"Offers from several sellers for the same product, with Load More"}),e[2]||(e[2]=o('<h3 id="what-each-offer-shows" tabindex="-1">What each offer shows <a class="header-anchor" href="#what-each-offer-shows" aria-label="Permalink to &quot;What each offer shows&quot;">​</a></h3><p>The top of the page shows the product&#39;s name, its overall star rating and the number of approved product reviews. Each offer below it shows:</p><ul><li><strong>The seller&#39;s business name</strong>, which opens the seller&#39;s shop page;</li><li><strong>The seller&#39;s star rating</strong>, the average of the seller&#39;s approved reviews;</li><li><strong>The price</strong> this seller charges;</li><li><strong>The seller&#39;s description</strong> of their offer, such as delivery or warranty details;</li><li><strong>A quantity box</strong> for a simple or virtual product, or the <strong>samples</strong> to download and the <strong>links</strong> to choose, each with its price, for a downloadable product;</li><li><strong>Add to Cart</strong>, which is greyed out when the offer can&#39;t be bought;</li><li><strong>Report Product</strong>, when the store lets customers report products. See <a href="./../moderation/seller-product-flagging">Seller &amp; Product Flagging</a>.</li></ul><h3 id="load-more-offers" tabindex="-1">Load more offers <a class="header-anchor" href="#load-more-offers" aria-label="Permalink to &quot;Load more offers&quot;">​</a></h3><p>The page shows five offers at a time. Click <strong>Load More</strong> below the last offer to add the next five, still in price order. The button disappears when every offer is shown.</p><h3 id="products-with-options" tabindex="-1">Products with options <a class="header-anchor" href="#products-with-options" aria-label="Permalink to &quot;Products with options&quot;">​</a></h3><p>For a product that comes in sizes or colours, choose the options on the product page first. The link then counts and opens the offers for that choice, and the offers page lists the chosen options under the product name. If the offers page is opened without a choice, it goes back to the product page with the message <strong>Options are missing for this product.</strong></p><h2 id="the-cart" tabindex="-1">The cart <a class="header-anchor" href="#the-cart" aria-label="Permalink to &quot;The cart&quot;">​</a></h2><ul><li>Each seller&#39;s product shows <strong>Sold By</strong> with the seller&#39;s business name under <strong>See Details</strong>.</li><li>The same product bought from two sellers stays on two separate lines.</li><li>Each product is charged at the price of the seller you chose.</li></ul>',9)),r(s,{src:"/images/shopping-across-sellers/cart-sellers.png",alt:"A cart with products from two sellers"}),e[3]||(e[3]=o('<h3 id="minimum-order-amounts" tabindex="-1">Minimum order amounts <a class="header-anchor" href="#minimum-order-amounts" aria-label="Permalink to &quot;Minimum order amounts&quot;">​</a></h3><p>When the store uses minimum order amounts, a seller can set the least a customer must spend with them in one order. When your products from that seller add up to less, the cart shows a message such as <strong>Minimum order amount for Urban Threads is: $25.00</strong>, and you can&#39;t check out until you add more from that seller.</p><h3 id="coupons" tabindex="-1">Coupons <a class="header-anchor" href="#coupons" aria-label="Permalink to &quot;Coupons&quot;">​</a></h3><ul><li>A coupon from a seller only lowers the price of that seller&#39;s products in your cart. See <a href="./../marketing/checkout-deals">Checkout Deals</a>.</li><li>A store coupon only lowers the price of the store&#39;s own products.</li><li>Only store coupons can discount shipping.</li></ul><h2 id="checkout-and-payment" tabindex="-1">Checkout and payment <a class="header-anchor" href="#checkout-and-payment" aria-label="Permalink to &quot;Checkout and payment&quot;">​</a></h2><p>Customers check out once for the whole cart. They choose one shipping method and pay the store once, even when the products come from several sellers.</p><p>After the order is placed, each seller sees their own products from it. Sellers ship them when the store lets sellers create shipments; otherwise the store ships them. Products from different sellers can arrive in separate packages.</p><h2 id="after-the-order" tabindex="-1">After the order <a class="header-anchor" href="#after-the-order" aria-label="Permalink to &quot;After the order&quot;">​</a></h2><p>From their account, customers can:</p><ul><li>ask for a return. See <a href="./../orders/return-merchandise-authorization">Returns (RMA)</a>;</li><li>message a seller. See <a href="./../customers/communications">Communications</a>.</li></ul><p>To review a seller, customers open the seller&#39;s shop page. See <a href="./seller-shop-page#review-a-seller">Seller Shop Page</a>.</p>',11))])}const w=t(n,[["render",i]]);export{g as __pageData,w as default};
